69	        Pageable sanitizedPageable = sanitizePageable(pageable);
70	
71	        log.debug("Fetching history for user={}, page={}, size={}, sort={}",
72	                  userId,
73	                  sanitizedPageable.getPageNumber(),
74	                  sanitizedPageable.getPageSize(),
75	                  sanitizedPageable.getSort());
76	
77	        try {
78	            Page<HistoryRecord> entityPage = historyRepository.findAll(
79	                    HistorySpecifications.byUserAndFilter(userId, filter),
80	                    sanitizedPageable);
81	
82	            List<HistoryRecordDto> dtoList =
83	                    entityPage.getContent().stream()
84	                              .map(historyMapper::toDto)
85	                              .collect(Collectors.toUnmodifiableList());
86	
87	            return new PageImpl<>(dtoList, sanitizedPageable, entityPage.getTotalElements());
88	        } catch (DataAccessException ex) {
89	            log.error("Data access error while fetching history for user={}", userId, ex);
90	            throw new HistoryQueryException("Unable to query history", ex);
