141	    // -----------------------------------------------------------------------
142	    // Internal helper methods
143	    // -----------------------------------------------------------------------
144	
145	    private Pageable sanitizePageable(Pageable pageable) {
146	        if (pageable == null) {
147	            pageable = PageRequest.of(0, 50, Sort.Direction.DESC, "requestedAt");
148	        }
149	
150	        if (pageable.getPageSize() > MAX_PAGE_SIZE) {
151	            throw new IllegalArgumentException(
152	                    "Page size exceeds maximum allowed of " + MAX_PAGE_SIZE);
153	        }
154	
155	        // Guarantee default sorting
156	        if (pageable.getSort().isUnsorted()) {
157	            pageable = PageRequest.of(
158	                    pageable.getPageNumber(),
159	                    pageable.getPageSize(),
160	                    Sort.Direction.DESC,
161	                    "requestedAt");
162	        }
163	        return pageable;
164	    }
