166	    // -----------------------------------------------------------------------
167	    // Exception type
168	    // -----------------------------------------------------------------------
169	
170	    /**
171	     * Service-level exception wrapping repository problems or invalid state.
172	     */
173	    public static class HistoryQueryException extends RuntimeException {
174	        public HistoryQueryException(String message, Throwable cause) {
175	            super(message, cause);
176	        }
177	    }
