183	    private static final class HistorySpecifications {
184	
185	        private HistorySpecifications() {
186	            /* utility */
187	        }
188	
189	        static org.springframework.data.jpa.domain.Specification<HistoryRecord> byUserAndFilter(
190	                String userId,
191	                HistoryFilter filter) {
192	
193	            return (root, query, cb) -> {
194	                // Mandatory predicate: ownership
195	                var predicates = new java.util.ArrayList<>(
196	                        Collections.singletonList(cb.equal(root.get("userId"), userId)));
197	
198	                if (filter != null) {
199	                    // Date range
200	                    if (filter.startDate() != null) {
201	                        predicates.add(cb.greaterThanOrEqualTo(
202	                                root.get("requestedAt"), filter.startDate()));
203	                    }
204	                    if (filter.endDate() != null) {
205	                        predicates.add(cb.lessThanOrEqualTo(
206	                                root.get("requestedAt"), filter.endDate()));
207	                    }
208	
209	                    // Utility type
210	                    if (filter.utilityType() != null) {
211	                        predicates.add(cb.equal(
212	                                root.get("utilityType"), filter.utilityType()));
213	                    }
214	
215	                    // Success only
216	                    if (Boolean.TRUE.equals(filter.successOnly())) {
217	                        predicates.add(cb.isTrue(root.get("successful")));
218	                    }
219	
220	                    // Free-text search
221	                    if (filter.searchTerm() != null && !filter.searchTerm().isBlank()) {
222	                        predicates.add(cb.like(
223	                                cb.lower(root.get("payload")),
224	                                "%" + filter.searchTerm().toLowerCase() + "%"));
225	                    }
226	                }
227	
228	                return cb.and(predicates.toArray(new jakarta.persistence.criteria.Predicate[0]));
229	            };
230	        }
231	    }
