30	 *
31	 * <p>This resolver delegates the heavy-lifting to the {@link HistoryReadService}
32	 * which encapsulates query-side business logic, caching and persistence concerns
33	 * (Repository Pattern). Validation is performed up-front via the javax.validation
34	 * API and in-method explicit guards. A {@link RateLimiter} is used to protect the
35	 * service layer against abuse.</p>
36	 *
37	 * <p>Cross-cutting concerns such as metrics and structured error handling
38	 * are applied inside the resolver to keep the rest of the code-base focused
39	 * on core business functionality.</p>
40	 */
41	@Slf4j
42	@Component
43	@RequiredArgsConstructor
44	@Validated
45	public class HistoryQueryResolver implements GraphQLQueryResolver {
46	
47	    private static final int DEFAULT_PAGE_SIZE = 20;
48	    private static final int MAX_PAGE_SIZE      = 200;
49	
50	    private final HistoryReadService historyReadService;
51	    private final RateLimiter historyQueryRateLimiter;
52	    private final Counter historyQuerySuccessCounter;
53	    private final Counter historyQueryFailureCounter;
54	
55	    /**
56	     * Constructor to wire Micrometer counters lazily when MeterRegistry is present.
57	     */
58	    public HistoryQueryResolver(
59	            @NonNull HistoryReadService historyReadService,
60	            @NonNull RateLimiter historyQueryRateLimiter,
61	            MeterRegistry meterRegistry) {
62	
63	        this.historyReadService          = historyReadService;
64	        this.historyQueryRateLimiter     = historyQueryRateLimiter;
65	        this.historyQuerySuccessCounter  = meterRegistry.counter("graphql.history.query.success");
66	        this.historyQueryFailureCounter  = meterRegistry.counter("graphql.history.query.failure");
67	    }
68	
69	    /**
70	     * GraphQL entry-point for retrieving a paginated slice of historical requests.
71	     *
72	     * @param pageInput page meta-data (page number, size, sorting)
73	     * @param filter    optional filtering criteria
74	     *
75	     * @return Paginated &amp; filtered collection of {@link HistoricalRequest}s wrapped by {@link HistoryPage}
76	     *
77	     * @throws GraphQLBadRequestException   when arguments fail validation
78	     * @throws GraphQLRateLimitException    when the caller exceeds the configured quota
79	     * @throws GraphQLUnexpectedException   on any uncaught exception
80	     */
81	    public HistoryPage history(
82	            @Valid PageInput pageInput,
83	            HistoryFilter filter) {
84	
85	        // Null-safe defaults
86	        PageInput resolvedPageInput = Objects.requireNonNullElseGet(
87	                pageInput,
88	                () -> new PageInput(0, DEFAULT_PAGE_SIZE, null, null));
89	
90	        // Rate-limiting — bubble up as GraphQL friendly error
91	        try {
92	            RateLimiter.waitForPermission(historyQueryRateLimiter);
93	        } catch (RequestNotPermitted e) {
94	            historyQueryFailureCounter.increment();
95	            throw new GraphQLRateLimitException("history");
96	        }
97	
98	        try {
99	            validatePageInput(resolvedPageInput);
100	            validateFilter(filter);
101	
102	            HistoryPage page = historyReadService.fetchHistory(resolvedPageInput, filter);
103	            historyQuerySuccessCounter.increment();
104	
105	            return page;
106	        } catch (GraphQLBadRequestException e) {
107	            historyQueryFailureCounter.increment();
108	            throw e;
109	        } catch (Exception ex) {
110	            // Defensive programming: we never leak implementation details to clients
111	            log.error("Unexpected error while fetching history", ex);
112	            historyQueryFailureCounter.increment();
113	            throw new GraphQLUnexpectedException();
114	        }
115	    }
116	
117	    /**
118	     * Validates pagination input beyond bean-validation.
119	     */
120	    private void validatePageInput(PageInput pageInput) {
121	
122	        int pageSize = pageInput.getSize() == null ? DEFAULT_PAGE_SIZE : pageInput.getSize();
123	
124	        if (pageInput.getPage() < 0) {
125	            throw new GraphQLBadRequestException("Page index must be equal or greater than 0.");
126	        }
127	        if (pageSize < 1 || pageSize > MAX_PAGE_SIZE) {
128	            throw new GraphQLBadRequestException(
129	                    "Page size must be within range 1.." + MAX_PAGE_SIZE + ".");
130	        }
131	    }
132	
133	    /**
134	     * Domain specific filter validation.
135	     */
136	    private void validateFilter(HistoryFilter filter) {
137	
138	        if (filter == null) {
139	            return;
140	        }
141	
142	        OffsetDateTime from = filter.getFrom();
143	        OffsetDateTime to   = filter.getTo();
144	
145	        if (from != null && to != null && from.isAfter(to)) {
146	            throw new GraphQLBadRequestException(
147	                    "'from' date-time must be earlier than or equal to 'to' date-time.");
148	        }
149	    }
150	}

