167	    /**
168	     * Customisation for Micrometer that adds common tags
169	     * and hides irrelevant meters.
170	     */
171	    static class MeterRegistryCustomizer implements
172	            io.micrometer.core.instrument.config.MeterFilter,
173	            java.util.function.Consumer<MeterRegistry> {
174	
175	        @Override
176	        public void accept(MeterRegistry registry) {
177	            registry.config().commonTags("application", "utilipulse-api");
178	        }
179	
180	        @Override
181	        public io.micrometer.core.instrument.config.MeterFilterReply accept(
182	                io.micrometer.core.instrument.Meter.Id id) {
183	
184	            // Hide JVM buffer metrics to keep the Prometheus surface clean.
185	            if (id.getName().startsWith("jvm.buffer")) {
186	                return io.micrometer.core.instrument.config.MeterFilterReply.DENY;
187	            }
188	            return io.micrometer.core.instrument.config.MeterFilterReply.NEUTRAL;
189	        }
190	    }
