192	    /**
193	     * Lightweight GraphQL instrumentation that logs execution time and errors.
194	     */
195	    static class LoggingInstrumentation extends SimpleInstrumentation {
196	
197	        private static final Logger gqlLog = LoggerFactory.getLogger("GraphQL");
198	
199	        @Override
200	        public InstrumentationContext<ExecutionResult> beginExecution(
201	                InstrumentationExecutionParameters parameters) {
202	
203	            long startNanos = System.nanoTime();
204	            return new InstrumentationContext<>() {
205	                @Override
206	                public void onDispatched(CompletableFuture<ExecutionResult> result) {
207	                }
208	
209	                @Override
210	                public void onCompleted(ExecutionResult result, Throwable t) {
211	                    long durationMs = (System.nanoTime() - startNanos) / 1_000_000;
212	                    if (t != null) {
213	                        gqlLog.error("GraphQL {} failed in {} ms: {}",
214	                                parameters.getOperation(), durationMs, t.getMessage(), t);
215	                    } else {
216	                        gqlLog.info("GraphQL {} completed in {} ms",
217	                                parameters.getOperation(), durationMs);
218	                    }
219	                }
220	            };
221	        }
222	    }
