224	    /**
225	     * Servlet filter that uses Bucket4j to enforce a simple IP-based
226	     * rate-limiting strategy.
227	     */
228	    static class RateLimitingFilter extends OncePerRequestFilter {
229	
230	        private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();
231	        private final Bandwidth limit;
232	
233	        RateLimitingFilter(long capacity, long refillTokens, Duration refillDuration) {
234	            this.limit = Bandwidth.classic(capacity, Refill.intervally(refillTokens, refillDuration));
235	        }
236	
237	        @Override
238	        protected void doFilterInternal(HttpServletRequest request,
239	                                        HttpServletResponse response,
240	                                        FilterChain filterChain)
241	                throws ServletException, IOException {
242	
243	            String key = resolveBucketKey(request);
244	            Bucket bucket = buckets.computeIfAbsent(key, k -> Bucket.builder().addLimit(limit).build());
245	
246	            if (bucket.tryConsume(1)) {
247	                response.addHeader("X-Rate-Limit-Remaining", String.valueOf(bucket.getAvailableTokens()));
248	                filterChain.doFilter(request, response);
249	            } else {
250	                handleLimitExceeded(response);
251	            }
252	        }
253	
254	        private String resolveBucketKey(HttpServletRequest request) {
255	            String forwarded = request.getHeader("X-Forwarded-For");
256	            if (forwarded != null && !forwarded.isBlank()) {
257	                return forwarded.split(",")[0].trim();
258	            }
259	            return request.getRemoteAddr();
260	        }
261	
262	        private void handleLimitExceeded(HttpServletResponse response) throws IOException {
263	            response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());
264	            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
265	            response.getWriter().write("""
266	                    {
267	                      "status": 429,
268	                      "error": "Too Many Requests",
269	                      "message": "Rate limit exceeded. Please try again later."
270	                    }
271	                    """);
272	        }
273	    }
274	}

71	    public static <T> PaginatedResponse<T> of(final List<T> content,
72	                                              final long totalElements,
73	                                              final int page,
74	                                              final int size,
75	                                              final URI requestUri) {
76	        Objects.requireNonNull(content, "content list must not be null");
77	        Objects.requireNonNull(requestUri, "requestUri must not be null");
78	
79	        int safeSize = Math.max(size, 1);
80	        int totalPages = (int) Math.ceil((double) totalElements / safeSize);
81	        int safePage = Math.max(page, 0);
82	
83	        PageMeta meta = new PageMeta(
84	                totalElements,
85	                totalPages,
86	                safePage,
87	                safeSize,
88	                safePage == 0,
89	                safePage >= totalPages - 1
90	        );
91	
92	        List<Link> navLinks = createNavigationLinks(requestUri, safePage, totalPages, safeSize);
93	
94	        return new Builder<T>()
95	                .withContent(content)
96	                .withMeta(meta)
97	                .withLinks(navLinks)
98	                .build();
99	    }
